  1	//! Service for ingesting entity search data
  2	//!
  3	
  4	use crate::domain::{
  5	    models::entity_ingestion::{
  6	        DeclarationIngestionStage, EntityIngestionError, EntityIngestionRequest,
  7	        EntityIngestionTarget,
  8	    },
  9	    repositories::{
 10	        entity_ingestion_pipline::EntityIngestionStorage, parliament_api::ParliamentApi,
 11	    },
 12	    services::entity_ingestion::interface::EntitySearchIngestionService,
 13	};
 14	
 15	mod interface;
 16	
 17	/// Allows users to search the databse using free text.
 18	#[derive(Clone)]
 19	pub struct Service<PS, PA> {
 20	    pipeline_storage: PS,
 21	    parliament_api: PA,
 22	}
 23	
 24	impl<PS, PA> Service<PS, PA> {
 25	    /// Creates a new instance
 26	    pub const fn new(pipeline_storage: PS, parliament_api: PA) -> Self {
 27	        Self {
 28	            pipeline_storage,
 29	            parliament_api,
 30	        }
 31	    }
 32	}
 33	
 34	impl<PS, PA> EntitySearchIngestionService for Service<PS, PA>
 35	where
 36	    PS: EntityIngestionStorage,
 37	    PA: ParliamentApi,
 38	{
 39	    /// Returns text search results for MPs and Funder entities.
 40	    ///
 41	    /// This function expects the repositories to return their results
 42	    /// in order where a higher score means a higher similarity.
 43	    async fn run_ingestion(
 44	        &self,
 45	        req: &EntityIngestionRequest,
 46	    ) -> Result<(), EntityIngestionError> {
 47	        match req.target() {
 48	            EntityIngestionTarget::Members => self.ingest_members().await,
 49	            EntityIngestionTarget::Declaration(stage) => match stage {
 50	                DeclarationIngestionStage::Import => self.ingest_declarations().await,
 51	                DeclarationIngestionStage::Clean => self.clean_funders().await,
 52	                DeclarationIngestionStage::Resolve => self.resolve_funders().await,
 53	            },
 54	        }
 55	    }
 56	}
 57	
 58	impl<PS, PA> Service<PS, PA>
 59	where
 60	    PA: ParliamentApi,
 61	{
 62	    async fn fetch_members(&self) -> Result<(), EntityIngestionError> {
 63	        self.parliament_api.get_sitting_members().await?;
 64	        Ok(())
 65	    }
 66	
 67	    async fn fetch_declarations(&self) -> Result<(), EntityIngestionError> {
 68	        self.parliament_api
 69	            .get_declarations_for_sitting_members()
 70	            .await?;
 71	        Ok(())
 72	    }
 73	}
 74	
 75	impl<PS, PA> Service<PS, PA>
 76	where
 77	    PS: EntityIngestionStorage,
 78	    PA: ParliamentApi,
 79	{
 80	    async fn ingest_members(&self) -> Result<(), EntityIngestionError> {
 81	        self.fetch_members().await?;
 82	        self.pipeline_storage.write_raw_data().await?;
 83	        Ok(())
 84	    }
 85	
 86	    async fn ingest_declarations(&self) -> Result<(), EntityIngestionError> {
 87	        self.fetch_declarations().await?;
 88	        self.pipeline_storage.write_raw_data().await?;
 89	        Ok(())
 90	    }
 91	}
 92	
 93	impl<PS, PA> Service<PS, PA>
 94	where
 95	    PS: EntityIngestionStorage,
 96	{
 97	    async fn clean_funders(&self) -> Result<(), EntityIngestionError> {
 98	        self.pipeline_storage.read_raw_data().await?;
 99	        self.pipeline_storage.write_cleaned_data().await?;
100	        Ok(())
101	    }
102	
103	    async fn resolve_funders(&self) -> Result<(), EntityIngestionError> {
104	        self.pipeline_storage.read_cleaned_data().await?;
105	        self.pipeline_storage.write_resolved_data().await?;
106	        Ok(())
107	    }
