  1	//! Contains entity ingestion models
  2	
  3	use std::str::FromStr;
  4	
  5	use strum::EnumString;
  6	use thiserror::Error;
  7	
  8	use crate::domain::repositories::{
  9	    entity_ingestion_pipline::EntitySearchPipelineError, parliament_api::ParliamentApiError,
 10	};
 11	
 12	/// Data required to search entities
 13	#[derive(Clone, Debug, PartialEq, Eq)]
 14	pub struct EntityIngestionRequest {
 15	    target: EntityIngestionTarget,
 16	}
 17	
 18	impl EntityIngestionRequest {
 19	    pub fn new_members_request() -> Self {
 20	        Self {
 21	            target: EntityIngestionTarget::Members,
 22	        }
 23	    }
 24	    pub fn new_declaration_request(stage: &str) -> Result<Self, EntityIngestionError> {
 25	        let stage = DeclarationIngestionStage::from_str(stage)
 26	            .map_err(|_| EntityIngestionError::InvalidStage(stage.to_string()))?;
 27	
 28	        Ok(Self {
 29	            target: EntityIngestionTarget::Declaration(stage),
 30	        })
 31	    }
 32	
 33	    pub fn target(&self) -> &EntityIngestionTarget {
 34	        &self.target
 35	    }
 36	}
 37	
 38	/// Ingestion targets
 39	#[derive(Clone, Debug, PartialEq, Eq)]
 40	pub enum EntityIngestionTarget {
 41	    /// MPs
 42	    Members,
 43	    /// Declarations, funders, funding entries
 44	    Declaration(DeclarationIngestionStage),
 45	}
 46	
 47	/// From what stage to run the declaration pipeline
 48	#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
 49	#[allow(missing_docs)]
 50	#[strum(ascii_case_insensitive)]
 51	pub enum DeclarationIngestionStage {
 52	    Import,
 53	    Clean,
 54	    Resolve,
 55	}
 56	
 57	/// Errors related to entity search
 58	#[derive(Error, Debug)]
 59	pub enum EntityIngestionError {
 60	    /// Errors related to the parliament API
 61	    #[error("error when retrieving data from the parliament API: {0}")]
 62	    ApiError(#[from] ParliamentApiError),
 63	
 64	    /// Generic error related to entity parsing, cleaning and resolution
 65	    #[error("error in ingestion pipeline: {0}")]
 66	    DataError(String),
 67	
 68	    /// Invalid strictness value
 69	    #[error("at least one entry must be expected to return")]
 70	    IoError(#[from] EntitySearchPipelineError),
 71	
 72	    /// Invalid stage
 73	    #[error("invalid stage provided: {0}")]
 74	    InvalidStage(String),
 75	}
