 14	    Server { config: PathBuf },
 15	    Data(DataArgs),
 16	}
 17	
 18	#[derive(Args)]
 19	struct DataArgs {
 20	    #[command(subcommand)]
 21	    command: DataCommands,
 22	}
 23	
 24	#[derive(Subcommand)]
 25	enum DataCommands {
 26	    Fetch { config: PathBuf },
 27	    Clean { config: PathBuf },
 28	    Resolve { config: PathBuf },
 29	}
 30	
 31	#[tokio::main]
 32	async fn main() -> anyhow::Result<()> {
 33	    let args = Cli::parse();
 34	
 35	    match args.command {
 36	        Commands::Server { config } => {
 37	            let config = Config::try_from(&config)?;
 38	            let _ = serve_exposed(&config).await?;
 39	        }
 40	        _ => panic!("only server commands supported"),
 41	    }
 42	
 43	    Ok(())
 44	}
