  1	//! File system interface for entity search ingestion
  2	
  3	use std::path::{self, PathBuf};
  4	
  5	use chrono::{DateTime, Utc};
  6	
  7	#[derive(Clone)]
  8	pub struct ExposedDataPipeline {
  9	    root: PathBuf,
 10	    key: DateTime<Utc>,
 11	    fs_schema: FsSchema,
 12	}
 13	
 14	#[derive(Clone)]
 15	struct FsSchema {
 16	    raw: String,
 17	    cleaned: String,
 18	    resolved: String,
 19	}
 20	
 21	impl Default for FsSchema {
 22	    fn default() -> Self {
 23	        Self {
 24	            raw: "raw".into(),
 25	            cleaned: "cleaned".into(),
 26	            resolved: "resolved".into(),
 27	        }
 28	    }
 29	}
 30	
 31	impl ExposedDataPipeline {
 32	    /// Creates a new instance of [`ExposedDataPipeline`]
 33	    pub fn new_with_key(root: &PathBuf, key: DateTime<Utc>) -> Self {
 34	        let root_abs = path::absolute(root).expect("valid root path must be provided");
 35	        Self {
 36	            root: root_abs,
 37	            key,
 38	            fs_schema: FsSchema::default(),
 39	        }
 40	    }
 41	
 42	    fn latest_run_path(&self) -> PathBuf {
 43	        self.root.join(self.key.to_string())
 44	    }
 45	
 46	    pub(super) fn raw_path(&self) -> PathBuf {
 47	        self.latest_run_path().join(&self.fs_schema.raw)
 48	    }
 49	
 50	    pub(super) fn cleaned_path(&self) -> PathBuf {
 51	        self.latest_run_path().join(&self.fs_schema.cleaned)
 52	    }
 53	
 54	    pub(super) fn resolved_path(&self) -> PathBuf {
 55	        self.latest_run_path().join(&self.fs_schema.resolved)
 56	    }
 57	}

